import{_ as a,o,c as r,ag as n}from"./chunks/framework.8tqBsFWt.js";const h=JSON.parse('{"title":"Your role in VERA","description":"","frontmatter":{},"headers":[],"relativePath":"guide/roles.md","filePath":"guide/roles.md"}'),t={name:"guide/roles.md"};function i(s,e,l,d,c,g){return o(),r("div",null,[...e[0]||(e[0]=[n('<h1 id="your-role-in-vera" tabindex="-1">Your role in VERA <a class="header-anchor" href="#your-role-in-vera" aria-label="Permalink to &quot;Your role in VERA&quot;">​</a></h1><p>Everyone using VERA has one of three roles. Your role determines what you can see and do — and how much of the console you can reach.</p><hr><h2 id="team-member" tabindex="-1">Team member <a class="header-anchor" href="#team-member" aria-label="Permalink to &quot;Team member&quot;">​</a></h2><p>The default role for anyone added to VERA.</p><p><strong>You can:</strong></p><ul><li>Log your own hours and review your own entries on the <strong>Time</strong> page</li><li>Request time off and track your requests on the <strong>Time Off</strong> page</li><li>See company holidays on the <strong>Calendar</strong> page</li></ul><p><strong>You can&#39;t:</strong></p><ul><li>See other people&#39;s time entries</li><li>See financial figures (costs, revenue, margin) or project deadlines</li><li>Reach the rest of the console — projects, allocations, capacity, and reports are manager/owner pages</li></ul><p>In the console, team members see the <strong>Time</strong>, <strong>Time Off</strong>, and <strong>Calendar</strong> pages. Everything else is reserved for managers and owners.</p><hr><h2 id="manager" tabindex="-1">Manager <a class="header-anchor" href="#manager" aria-label="Permalink to &quot;Manager&quot;">​</a></h2><p>Managers are typically project leads or account managers, assigned to one or more projects.</p><p><strong>In addition to everything a team member can do, you can:</strong></p><ul><li>See time logged by anyone on your assigned projects</li><li>See project health and burn rates as <strong>percentages</strong> — not dollar values</li><li>Approve or decline time-off requests</li><li>Log hours on behalf of team members (e.g. sick days, leave)</li><li>See project deadlines for your projects</li><li>Manage allocations (envelopes) and see who&#39;s on your projects with their remaining hours</li></ul><p><strong>You can&#39;t see:</strong></p><ul><li>Financial figures (costs, revenue, margin)</li><li>Projects you&#39;re not assigned to manage</li></ul><p>Managers get the full console navigation.</p><hr><h2 id="owner" tabindex="-1">Owner <a class="header-anchor" href="#owner" aria-label="Permalink to &quot;Owner&quot;">​</a></h2><p>Owners have full visibility across everything.</p><p><strong>In addition to everything a manager can do, you can:</strong></p><ul><li>See all projects, not just assigned ones</li><li>See all financial data: costs, revenue, margins, billing rates</li><li>See and manage rate history for the team</li><li>Create and cancel vendor liabilities</li><li>Add and manage team members, and set their roles</li><li>Create projects and set budgets, deadlines, and billing rates</li><li>Manage clients, tasks, disciplines, and company holidays</li><li>See the full reports, including P&amp;L</li></ul><hr><h2 id="how-roles-are-assigned" tabindex="-1">How roles are assigned <a class="header-anchor" href="#how-roles-are-assigned" aria-label="Permalink to &quot;How roles are assigned&quot;">​</a></h2><p>Roles are set by an owner from the <strong>Users</strong> page in the console. If you believe your role is wrong — for example, you&#39;re managing projects but can&#39;t see the right data — ask whoever administers VERA to update it.</p><hr><h2 id="a-note-on-financial-data" tabindex="-1">A note on financial data <a class="header-anchor" href="#a-note-on-financial-data" aria-label="Permalink to &quot;A note on financial data&quot;">​</a></h2><p>Dollar figures are visible to owners only, by design. Managers see percentages — &quot;this project is at 73% of its budget&quot; — but not the underlying cost or contract value. This is intentional: financial context without the full picture can create more confusion than clarity.</p>',29)])])}const p=a(t,[["render",i]]);export{h as __pageData,p as default};
